func flCopy(from *port.Cells, to *port.Cells) int32 {
	// The stage takes the furniture's lines out of `lines` in place, as the Engine lets it: every run gets a copy.
	var i int32 = 0
	port.CellsDrop(to, 0)
	for i < port.CellsLen(from) {
		port.CellsPush(to, port.CellsAt(from, i))
		i += 1
	}
	return 0
}

func flOrder(ln *port.Cells) int32 {
	// Put the rows of `lines` in page order, as the content interpreter writes them (a stable insertion sort: the tests add
	// a page's furniture after the next pages' body).
	var n int32 = evidence.LnCount(ln)
	var i int32 = 1
	var j int32 = 0
	var k int32 = 0
	var a int32 = 0
	var b int32 = 0
	for i < n {
		j = i
		for (j > 0) && (evidence.LnGet(ln, j-1, evidence.LhPage()) > evidence.LnGet(ln, j, evidence.LhPage())) {
			k = 0
			for k < 16 {
				a = evidence.LnGet(ln, j-1, k)
				b = evidence.LnGet(ln, j, k)
				evidence.LnSet(ln, j-1, k, b)
				evidence.LnSet(ln, j, k, a)
				k += 1
			}
			j -= 1
		}
		i += 1
	}
	return 0
}

func flBrief(t *strings.Builder, nodes *port.Cells, attrs *port.Cells, text *port.Cells, pages *port.Cells, ledger *port.Cells, body int32) int32 {
	// What the stage decided, in the brief of the head of this file.
	var np int32 = model.PageCount(pages)
	var nn int32 = model.NodeCount(nodes)
	var nl int32 = model.LedgerCount(ledger)
	var i int32 = 0
	var k int32 = 0
	var a int32 = 0
	var c int32 = 0
	var s int32 = 0
	var first int32 = 1
	for i < np {
		if model.PageLabelLen(pages, i) > 0 {
			port.TextAscii(t, "L")
			port.TextI32(t, i+1)
			port.TextCp(t, 61)
			s = model.PageLabelStart(pages, i)
			k = 0
			for k < model.PageLabelLen(pages, i) {
				port.TextCp(t, model.TextAt(text, s+k))
				k += 1
			}
			port.TextCp(t, 59)
		}
		i += 1
	}
	i = 0
	for i < nn {
		if (model.NodeKind(nodes, i) == model.NkFurniture()) && (model.NodeParent(nodes, i) == -1) {
			port.TextCp(t, 70)
			if model.NodeSub(nodes, i) == model.RlHeader() {
				port.TextCp(t, 104)
			}
			if model.NodeSub(nodes, i) == model.RlFooter() {
				port.TextCp(t, 102)
			}
			if model.NodeSub(nodes, i) == model.RlMargin() {
				port.TextCp(t, 109)
			}
			a = model.NodeAttr(nodes, attrs, i, model.FkPages())
			first = 1
			for a >= 0 {
				if first == 0 {
					port.TextCp(t, 44)
				}
				first = 0
				port.TextI32(t, model.AttrValue(attrs, a))
				a = model.AttrFindNext(attrs, a, model.FkPages())
			}
			port.TextCp(t, 58)
			s = model.NodeTextStart(nodes, i)
			k = 0
			for k < model.NodeTextLen(nodes, i) {
				port.TextCp(t, model.TextAt(text, s+k))
				k += 1
			}
			port.TextCp(t, 59)
		}
		i += 1
	}
	i = 0
	for i < nl {
		port.TextCp(t, 68)
		if model.LedgerReason(ledger, i) == model.DrPageNumber() {
			port.TextCp(t, 112)
		}
		if model.LedgerReason(ledger, i) == model.DrRunningTitle() {
			port.TextCp(t, 114)
		}
		if model.LedgerReason(ledger, i) == model.DrWatermark() {
			port.TextCp(t, 119)
		}
		port.TextCp(t, 64)
		port.TextI32(t, model.LedgerPage(ledger, i))
		port.TextCp(t, 58)
		s = model.LedgerTextStart(ledger, i)
		k = 0
		for k < model.LedgerTextLen(ledger, i) {
			port.TextCp(t, model.TextAt(text, s+k))
			k += 1
		}
		port.TextCp(t, 59)
		i += 1
	}
	i = 0
	for (i < nn) && (body == 1) {
		if model.NodeKind(nodes, i) == model.NkParagraph() {
			port.TextAscii(t, "P:")
			s = model.NodeTextStart(nodes, i)
			k = 0
			for k < model.NodeTextLen(nodes, i) {
				port.TextCp(t, model.TextAt(text, s+k))
				k += 1
			}
			// a paragraph across a page's end has its text in inlines: `text`, then `|` for the milestone, then `text`
			c = model.NodeFirstChild(nodes, i)
			for c >= 0 {
				if model.NodeKind(nodes, c) == model.NkBreak() {
					port.TextCp(t, 124)
				}
				s = model.NodeTextStart(nodes, c)
				k = 0
				for (s >= 0) && (k < model.NodeTextLen(nodes, c)) {
					port.TextCp(t, model.TextAt(text, s+k))
					k += 1
				}
				c = model.NodeNext(nodes, c)
			}
			port.TextCp(t, 59)
		}
		i += 1
	}
	return 0
}

