func TestANumberAloneAtTheFootOf_everyPageIsAPageNumber(emonT *testing.T) {
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var txt *port.Cells = port.NewCells()
	var md *port.Cells = port.NewCells()
	var lb *port.Cells = port.NewCells()
	var t1 *strings.Builder = port.NewText()
	var t2 *strings.Builder = port.NewText()
	var t3 *strings.Builder = port.NewText()
	// Four pages, a bare number centred in the bottom margin: dropped from the flow, kept as the page's label.
	flPages(wd, ln, et, 4)
	flBottom(wd, ln, et, port.TextBlob("1"), 1, 30000, 31000)
	flBottom(wd, ln, et, port.TextBlob("2"), 2, 30000, 31000)
	flBottom(wd, ln, et, port.TextBlob("3"), 3, 30000, 31000)
	flBottom(wd, ln, et, port.TextBlob("4"), 4, 30000, 31000)
	port.AssertEq(emonT, flRun(wd, ln, et, 4, 0, 0, txt, md, lb, t1), 0, "number: well formed")
	port.AssertText(emonT, t1, "L1=1;L2=2;L3=3;L4=4;Dp@1:1;Dp@2:2;Dp@3:3;Dp@4:4;P:alpha beta. |alpha beta. |alpha beta. |alpha beta.;", "page numbers: labels, ledger rows, and not a word of them in the body")
	// `keep`: nothing leaves the flow (the labels of /PageLabels would still come, but there are none).
	port.AssertEq(emonT, flRun(wd, ln, et, 4, 0, 1, txt, md, lb, t2), 0, "keep: well formed")
	port.AssertText(emonT, t2, "P:alpha beta.;P:1;P:alpha beta.;P:2;P:alpha beta.;P:3;P:alpha beta.;P:4;", "keep: every line stays where it was")
	// `drop` takes the same here: a page number is dropped by the policy too.
	port.AssertEq(emonT, flRun(wd, ln, et, 4, 0, 2, txt, md, lb, t3), 0, "drop: well formed")
	port.AssertText(emonT, t3, "L1=1;L2=2;L3=3;L4=4;Dp@1:1;Dp@2:2;Dp@3:3;Dp@4:4;P:alpha beta. |alpha beta. |alpha beta. |alpha beta.;", "drop: the same")
}

