func TestPageLabelsOfTheCatalogueWinOverThePrintedNumbers(emonT *testing.T) {
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var txt *port.Cells = port.NewCells()
	var md *port.Cells = port.NewCells()
	var lb *port.Cells = port.NewCells()
	var t1 *strings.Builder = port.NewText()
	var i int32 = 0
	// Two pages numbered 5 and 6 at the foot, and a catalogue that says lower roman from page 0 (ii at page 2): the labels
	// are the catalogue's, the printed numbers are still taken out of the flow.
	flPages(wd, ln, et, 2)
	flBottom(wd, ln, et, port.TextBlob("5"), 1, 30000, 31000)
	flBottom(wd, ln, et, port.TextBlob("6"), 2, 30000, 31000)
	for i < 60 {
		port.CellsPush(md, 0)
		i += 1
	}
	port.CellsSet(md, 54, 1)
	// one range: first page 0, style r (3), no prefix, number 1 on the first page, 1 + the pages after the last, no bits
	port.CellsPush(lb, 0)
	port.CellsPush(lb, 3)
	port.CellsPush(lb, -1)
	port.CellsPush(lb, 0)
	port.CellsPush(lb, 1)
	port.CellsPush(lb, 2)
	port.CellsPush(lb, 0)
	port.CellsPush(lb, 0)
	port.AssertEq(emonT, flRun(wd, ln, et, 2, 0, 0, txt, md, lb, t1), 0, "labels: well formed")
	port.AssertText(emonT, t1, "L1=i;L2=ii;Dp@1:5;Dp@2:6;P:alpha beta. |alpha beta.;", "the catalogue's labels, the printed numbers dropped")
}

func flFile(blob []byte, mode int32, t *strings.Builder) int32 {
	// A real file through the whole pipeline as the Engine runs it, and the brief of the Model. Answers 0, or the open
	// status, or -1.
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var pg *port.Cells = port.NewCells()
	var idx *port.Cells = port.NewCells()
	var txt *port.Cells = port.NewCells()
	var w *port.Cells = port.NewCells()
	var seen *port.Cells = port.NewCells()
	var md *port.Cells = port.NewCells()
	var xm *port.Cells = port.NewCells()
	var ol *port.Cells = port.NewCells()
	var lb *port.Cells = port.NewCells()
	var nd *port.Cells = port.NewCells()
	var nt *port.Cells = port.NewCells()
	var cx *port.Cells = port.NewCells()
	var ox *port.Cells = port.NewCells()
	var cs *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var f0 *port.Cells = port.NewCells()
	var f1 *port.Cells = port.NewCells()
	var f2 *port.Cells = port.NewCells()
	var f3 *port.Cells = port.NewCells()
	var gl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var mk *port.Cells = port.NewCells()
	var fnt *port.Cells = port.NewCells()
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var ss *port.Cells = port.NewCells()
	var se *port.Cells = port.NewCells()
	var sk *port.Cells = port.NewCells()
	var sc *port.Cells = port.NewCells()
	var so *port.Cells = port.NewCells()
	var sa *port.Cells = port.NewCells()
	var wk *port.Cells = port.NewCells()
	var ha *port.Cells = port.NewCells()
	var hb *port.Cells = port.NewCells()
	var hh *port.Cells = port.NewCells()
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var ord *port.Cells = port.NewCells()
	var raw *port.Cells = port.NewCells()
	var tmp *port.Cells = port.NewCells()
	var fr *port.Cells = port.NewCells()
	var gp *port.Cells = port.NewCells()
	var cd *port.Cells = port.NewCells()
	var sl *port.Cells = port.NewCells()
	var gr *port.Cells = port.NewCells()
	var ford *port.Cells = port.NewCells()
	var tx *port.Cells = port.NewCells()
	var bh *port.Cells = port.NewCells()
	var fo *port.Cells = port.NewCells()
	var fp *port.Cells = port.NewCells()
	var ft *port.Cells = port.NewCells()
	var pl *port.Cells = port.NewCells()
	var chk *port.Cells = port.NewCells()
	var pa *port.Cells = port.NewCells()
	var im *port.Cells = port.NewCells()
	var pts *port.Cells = port.NewCells()
	var gx *port.Cells = port.NewCells()
	var pdf *port.Src = port.SrcOfBlob(blob)
	var status int32 = 0
	var r int32 = 0
	var np int32 = 0
	status = pdfdoc.PdOpen(pdf, ar, dc, a, b, st)
	if status != 0 {
		return status
	}
	r = pdfcontent.PcDocument(pdf, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx)
	if r != 0 {
		return -1
	}
	np = pdfdoc.PdPgCount(pg)
	pdfx.PxIndexBuild(pdf, ar, dc, a, b, st, pg, idx)
	r = pdfmeta.PmRun(pdf, ar, dc, a, b, st, pg, idx, txt, w, seen, md, xm, ol, lb, nd, nt)
	if r < 0 {
		return -1
	}
	r = pdfstruct.TgRead(pdf, ar, dc, a, b, st, pg, idx, txt, w, seen, ss, se, sk, sc, so, wk, md)
	if r < 0 {
		return -1
	}
	r = pdfstruct.TgJoin(ss, se, sk, sc, so, sa, gl, mk, fnt, pg, ha, hb, hh)
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	para.PaPages(pg, pages)
	furniture.FuFind(wd, ln, et, gl, mk, pages, np, txt, md, lb, pdfstruct.TgTrust(ss), mode, cd, sl, gr, ford, tx, bh, fo, fp, ft, pl)
	flBuild(wd, ln, et, np, pages, layout, nodes, attrs, regions, text, ord, raw, tmp, fr, gp)
	furniture.FuWrite(fo, fp, ft, pl, np, nodes, attrs, regions, text, pages, ledger, tmp)
	flBrief(t, nodes, attrs, text, pages, ledger, 0)
	r = model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, chk)
	return r
}

func TestTheTaggedFixturesLoseTheirRunningHeaderFooterAndWatermark(emonT *testing.T) {
	// `good.pdf` is tagged (its running header, footer and DRAFT watermark are /Artifact marked content: the tree is trusted);
	// `bad.pdf` says the same page wrongly (the running header is tagged P, a heading is marked Footer): the geometry and the
	// repetition still find the furniture, whatever the tree says (D034, D076). Each page has `Page N` and `Quarterly Report`.
	var t1 *strings.Builder = port.NewText()
	var t2 *strings.Builder = port.NewText()
	var t3 *strings.Builder = port.NewText()
	port.AssertEq(emonT, flFile(port.TestFile("pdf/tagged/good.pdf"), 0, t1), 0, "good: well formed")
	port.AssertText(emonT, t1, "L1=1;L2=2;Dr@1:Quarterly Report;Dr@2:Quarterly Report;Dp@1:Page 1;Dp@2:Page 2;Dw@1:DRAFT;", "good: header, footer, watermark out, the content as it was")
	port.AssertEq(emonT, flFile(port.TestFile("pdf/tagged/bad.pdf"), 0, t2), 0, "bad: well formed")
	port.AssertText(emonT, t2, "L1=1;L2=2;Dr@1:Quarterly Report;Dr@2:Quarterly Report;Dp@1:Page 1;Dp@2:Page 2;Dw@1:DRAFT;", "bad: the same page told wrongly by the tree is cleaned up the same way (D034: verified, not obeyed)")
	port.AssertEq(emonT, flFile(port.TestFile("pdf/tagged/good.pdf"), 1, t3), 0, "good, keep: well formed")
	port.AssertText(emonT, t3, "", "keep: nothing leaves the flow, and nothing is said")
}

